/**
 * ------------------------------------------------------
 *  TYPE DEFINITIONS
 * ------------------------------------------------------
 *  These interfaces define the structure of plans and
 *  steps used throughout the workflow engine.
 *
 *  PlanStep:
 *    A single executable action (e.g., read file, write file,
 *    search the web, update memory).
 *
 *  Plan:
 *    An ordered list of PlanStep objects. This is the main
 *    structure passed into executePlan().
 *
 *  StepValidationResult / PlanValidationResult:
 *    Used by the validation subsystem to ensure correctness
 *    before execution.
 *
 *  DAG:
 *    Directed Acyclic Graph used for dependency resolution
 *    and parallel execution.
 */

// -------------------------------------------------------------
//  PLAN + STEP TYPE DEFINITIONS
// -------------------------------------------------------------
//  These interfaces define the structure of executable plans
//  and their steps. They are used throughout the workflow engine
//  for validation, optimization, and execution.
// -------------------------------------------------------------

export interface PlanStep {
  number: number;           // Step number (1-based, stable across rewrites)
  tool: string;             // Tool name (must exist in toolRegistry)
  description?: string;   // Optional readable description of the step's purpose

  // Tool-specific fields (only some apply depending on the tool)
  filename?: string;
  content?: string;
  mode?: string;
  query?: string;
  key?: string;
  value?: string;

  // Execution behavior modifiers
  retry?: number;           // Number of retry attempts allowed
  autofix?: boolean;        // Whether LLM autofix is allowed for this step
  parallelGroup?: number;   // Assigned parallel execution group
}

export interface Plan {
  goal?: string;       // High-level goal (optional metadata)
  optimize?: boolean;  // Whether to run optimization pipeline
  parallel?: boolean;  // Whether to enable parallel execution
  autofix?: boolean;   // Whether autofix is enabled for the plan
  steps: PlanStep[];   // Ordered list of steps
}

export interface StepValidationResult {
  valid: boolean;
  error?: string;       // Error message if validation fails
}

export interface PlanValidationResult {
  valid: boolean;
  errors: string[];   // List of validation errors
}

export interface StepExecutionResult {
  step: number | null;          // Step number executed
  description?: string | null;  // Step description
  tool: string | null;          // Tool used
  parallelGroup?: number | null;

  startTime: number | null;
  endTime: number | null;
  durationMs: number | null;

  output: unknown;         // Tool output
  error: unknown;          // Error details if execution failed

  autofixAttempted: boolean;    // Whether autofix was triggered
  fixedStep?: PlanStep | null;  // Step after autofix (if applicable)
}

export interface DAG {
  adjacencyList: Map<number, number[]>;         // Forward edges 
  reverseAdjacencyList: Map<number, number[]>;  // Reverse edges
  inDegree: Map<number, number>;                // Node dependency counts
}

