// =============================================================
//  BLOCK 2 — VALIDATION + AUTOFIX SUBSYSTEM
// =============================================================
//  This subsystem ensures that each step in a plan is valid,
//  well‑formed, and executable. If a step fails validation or
//  execution, the LLM attempts to automatically rewrite it.
//
//  Responsibilities:
//    • Step-level validation
//    • Plan-level validation
//    • LLM-powered step rewriting (autofix)
//    • Retry logic for corrected steps
//    • Ensuring required fields exist for each tool
//
//  This subsystem is the first line of defense against malformed
//  plans and is essential for safe autonomous execution.
// =============================================================


/**
 * -------------------------------------------------------------
 *  executeSingleStep()
 * -------------------------------------------------------------
 *  Executes a single plan step using the tool registry.
 *
 *  Responsibilities:
 *    • Validate required fields for the selected tool
 *    • Call the tool handler with the correct arguments
 *    • Return the tool output or throw on missing fields
 *
 *  Used by:
 *    • Normal execution
 *    • Retry logic
 *    • Autofix execution attempts
 */
async function executeSingleStep(step: PlanStep): Promise<unknown> {
  const entry = toolRegistry[step.tool];

  if (!entry) {
    return { success: false, error: `Unknown tool: ${step.tool}` };
  }

  // Validate required fields
  for (const field of entry.requiredFields || []) {
    if ((step as any)[field] === undefined) {
      throw new Error(`Missing required field "${field}" for tool "${step.tool}"`);
    }
  }

  // Execute the tool
  return await entry.handler(
    step.filename,
    step.content,
    step.mode,
    step.query,
    step.key,
    step.value,
    step.description
  );
}

// -------------------------------------------------------------
//  RETRY LOGIC
// -------------------------------------------------------------
/**
 * Simple wrapper around executeSingleStep().
 * Exists to make retry logic explicit and readable.
 */
async function retryStep(step: PlanStep): Promise<unknown> {
  return await executeSingleStep(step);
}

// -------------------------------------------------------------
//  LLM AUTOFIX — REWRITE SINGLE STEP
// -------------------------------------------------------------
/**
 * Uses the LLM to rewrite a failing step.
 *
 * Inputs:
 *   • step  — the original failing step
 *   • error — the error thrown during execution
 *
 * LLM Responsibilities:
 *   • Return a corrected JSON version of the step
 *   • Preserve the step number
 *   • Preserve the tool unless clearly incorrect
 *   • Ensure all required fields for the tool are present
 *   • Output ONLY valid JSON (no commentary)
 *
 * This function is the core of the autofix mechanism.
 */
async function rewriteStep(step: PlanStep, error: unknown): Promise<PlanStep> {
  const completion = await client.chat.completions.create({
    model: "gpt-4o-mini",
    messages: [
      {
        role: "system",
        content: `
${vectorSystemPrompt}

You are fixing a failing plan step for an autonomous agent.

Available tools:
${Object.keys(toolRegistry).join(", ")}

Tool schemas:
${JSON.stringify(toolRegistry, null, 2)}

Your job:
- Return a corrected version of the step as valid JSON.
- Keep the same "number" and "tool" unless the tool is clearly wrong.
- Ensure all required fields for that tool are present.
- Do NOT include commentary, only JSON.
        `
      },
      {
        role: "user",
        content: `
Original step:
${JSON.stringify(step, null, 2)}

Error:
${JSON.stringify(error, null, 2)}
        `
      }
    ]
  });

  const fixedJson = completion.choices[0].message.content ?? "";
  return JSON.parse(fixedJson);
}

// -------------------------------------------------------------
//  STEP VALIDATION
// -------------------------------------------------------------
//  Ensures a single step is structurally valid before execution.
//  Checks:
//    • Tool exists in the registry
//    • All required fields for that tool are present
// -------------------------------------------------------------
function validateStep(step: PlanStep): StepValidationResult {
  const entry = toolRegistry[step.tool];

  if (!entry) {
    return {
      valid: false,
      error: `Unknown tool "${step.tool}". Valid tools: ${Object.keys(toolRegistry).join(", ")}`
    };
  }

  for (const field of entry.requiredFields || []) {
    if ((step as any)[field] === undefined || (step as any)[field] === null) {
      return {
        valid: false,
        error: `Missing required field "${field}" for tool "${step.tool}".`
      };
    }
  }

  return { valid: true };
}

// -------------------------------------------------------------
//  PLAN VALIDATION
// -------------------------------------------------------------
//  Validates the entire plan before execution.
//  Ensures:
//    • Steps exist
//    • Each step passes validateStep()
//    • No structural issues before optimization or execution
// -------------------------------------------------------------
function validatePlan(plan: Plan): PlanValidationResult {
  const errors: string[] = [];

  if (!plan.steps || !Array.isArray(plan.steps) || plan.steps.length === 0) {
    errors.push("Plan must contain at least one step.");
    return { valid: false, errors };
  }

  const seenNumbers = new Set<number>();

  for (const step of plan.steps) {
    if (step.number === undefined || step.number === null) {
      errors.push("A step is missing its 'number' field.");
      continue;
    }

    if (seenNumbers.has(step.number)) {
      errors.push(`Duplicate step number detected: ${step.number}`);
    }
    seenNumbers.add(step.number);

    if (!step.tool) {
      errors.push(`Step ${step.number} is missing a 'tool' field.`);
      continue;
    }

    if (!toolRegistry[step.tool]) {
      errors.push(`Step ${step.number} uses unknown tool "${step.tool}".`);
      continue;
    }

    const required = toolRegistry[step.tool].requiredFields || [];
    for (const field of required) {
      if ((step as any)[field] === undefined || (step as any)[field] === null) {
        errors.push(
          `Step ${step.number} is missing required field "${field}" for tool "${step.tool}".`
        );
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

